    setInterval:(fn,ms)=>{ const k='w'+(++n); alive[k]=true; const loop=()=>{ if(!alive[k]) return; set(()=>{ if(!alive[k]) return; try{ const r=fn(); if(r&&r.catch) r.catch(()=>{}); }catch(e){} loop(); },ms); }; loop(); return k; },
