async function(){ const B=window.SGSBOT; B.krRound=-1;
  const MUST=new Set(['發憤圖強','偽裝','反擊','調虎離山']);   // 孔融重鑄: 除非有一定要保留的牌, 否則盡量重鑄越多越好
